"""Keeps the README's key-findings block in sync with the package (between <!-- findings:start/end --> markers)."""
from __future__ import annotations
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
START, END = "<!-- findings:start -->", "<!-- findings:end -->"


def block() -> str:
    from .site import findings
    F = findings()
    rows = [("Power switches", f"Diamond's ideal figure of merit is **{F['BFOMratio']}×** silicon's, but only **{F['FionDriftPct']}%** of the boron in a bulk-doped 1,200 V drift is ionized at room temperature. **Diamond wins when hot:** silicon carbide's EV-inverter loss is **{F['PowerRatioHot']}×** diamond's at a 250 °C junction (median {F['UncPowerHotPfifty']}× with material uncertainty); at 300 K the ratio is {F['PowerRatioRoom']}× (median {F['UncPowerPfifty']}×), so a bulk-doped diamond switch loses. Delta-doped and hole-gas devices avoid the ionization penalty (proposed here).", "[E9](docs/expert/E9_power_circuits_diamond_vs_gan_sic.md), [Confidence](docs/VALIDATION.md)"),
            ("Two-qubit gates", f"For the published room-temperature NV pair, coherence alone allows a Bell fidelity of **{F['FcohLow']} to {F['FcohHigh']}**, depending on the noise spectrum and the number of gate applications (model of this repository). The measured **0.67** [dolde2013] lies below that whole range: a known discrepancy that the framework does not yet explain. The earlier reading, that the charge state was ready only {F['qForSixtySeven']} of the time, is withdrawn.", "[E5](docs/expert/E5_nv_qubit_engineering.md), [audit Q1](docs/AUDIT.md)"),
            ("Error correction", f"With two-level qubits only CZ gates keep a noise bias; CNOTs keep at most η ≈ {F['EtaCnot']} [etxezarreta2025]. In that model, at bias 100 on CZ, the native XZZX code's threshold is **{F['ThrXZZXBias']}%** against {F['ThrCSSBias']}% for the standard code (model of this repository; the published two-level study finds the same roughly twofold rise, to 1.27%, with a different noise model [etxezarreta2025]). Bias-preserving CNOTs would give {F['ThrXZZXUpper']}%, an upper bound no two-level qubit reaches.", "[E6.1e](docs/expert/E6_error_correction_and_system_architecture.md)"),
            ("Machine size", f"RSA-2048, with the logical step count calibrated so that the published superconducting parameters give the published 8 hours ({F['RSAStepsCal']}×10⁹ steps [gidney2021]), takes **{F['RSAYears']} years** at 1 ms readout on a {F['RSADieMm']} mm die ({F['UncQPten']} to {F['UncQPninety']} years with uncertainty); counting every Toffoli as a serial step gives an upper bound of {F['RSAYearsToffoli']} years. The inter-cell link is an assumption (proposed here). With biased gate noise the standard code needs {F['RSAQubitsMCSSBiased']} M qubits and the XZZX code **{F['RSAQubitsMXZZX']} M**.", "[E10.5c](docs/expert/E10_scaling_a_room_temperature_quantum_computer.md)"),
            ("What to measure next", f"Diamond hole mobility explains about {F['SobolMobility']} of the power-ratio spread and its critical field {F['SobolField']}; readout time explains {F['SobolReadout']} of the runtime spread. Per dollar, a few-thousand-dollar **Hall measurement of diamond mobility** comes first.", "[E10.5d](docs/expert/E10_scaling_a_room_temperature_quantum_computer.md)"),
            ("Evidence", f"**{F['ValPass']} of {F['ValChecks']}** validation checks pass (the others are explained discrepancies); {F['NumRefs']} references; {F['NumFigures']} figures regenerated from code. The [audit](docs/AUDIT.md) lists every claim that was corrected.", "[VALIDATION.md](docs/VALIDATION.md)")]
    return "\n".join([START, "| | Result (generated by `adamas build docs`) | Details |", "|---|---|---|"] + [f"| **{a}** | {b} | {c} |" for a, b, c in rows] + [END])


def update(path: Path = ROOT / "README.md") -> bool:
    s = path.read_text(encoding="utf-8"); a, b = s.index(START), s.index(END) + len(END)
    new = s[:a] + block() + s[b:]
    if new != s:
        path.write_text(new, encoding="utf-8"); return True
    return False


def write() -> str:
    update(); return "README.md (key findings)"
